window.products.push({"id":870832,"name":"Family Holiday Christmas You've Been Naughty Bag o'Coal in a Burlap Bag with Drawstring Stocking Stuffer (Pack of 3)","category":"homeandappliances","retail price":10.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71Rv3-uoOCL._AC_SL1000_.jpg","description":"'Tis the Season for Stocking Stuffers. Give the gift of silliness during your holiday party with a Bag O' Coal! Your friends, family, or co-workers will love receiving these super cute bags during a white elephant exchange or secret Santa fun to make them ask how they behaved this year! 3 bags per package. The drawstring bag is approximately 4\" wide and 5 1/2\" tall. Include 2 lumps of coals. Bags read, \"You've been naughty.\" Make memories this Christmas with fun holiday favors, toys, and gifts. Stock up on everything you need to make your Christmas season complete!","images":["https://m.media-amazon.com/images/I/71Rv3-uoOCL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Family Holiday","source_asin":"B07YNZXS5L","category_path":"Home & Kitchen"},"sku":"BM-870832","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07YNZXS5L","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07YNZXS5L","price_pending":true,"merchant_ready":false});
